mapper.select:
SELECT * FROM material_purchases
WHERE tenant_id = #{tenantId}
ORDER BY purchase_date DESC

mapper.insert:
INSERT INTO material_purchases (
    tenant_id, material_name, material_category, quantity, unit,
    unit_price, total_amount, supplier, purchase_date, payment_status,
    payment_method, notes, created_at, updated_at, created_by, updated_by
) VALUES (
    #{tenantId}, #{materialName}, #{materialCategory}, #{quantity}, #{unit},
    #{unitPrice}, #{totalAmount}, #{supplier}, #{purchaseDate}, #{paymentStatus},
    #{paymentMethod}, #{notes}, NOW(), NOW(), #{createdBy}, #{updatedBy}
)
